<template><el-drawer :title="heading" :visible.sync="visible" size="min(1320px,97vw)" append-to-body :wrapper-closable="false"><div v-loading="loading" class="binding-workspace"><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="binding"><div class="compare"><aside><div class="label">平台商品</div><el-image v-if="binding.pic_url" :src="binding.pic_url" fit="contain" class="picture"/><h3>{{ binding.title }}</h3><div class="spec">{{ binding.spec_name || '无规格' }}</div><el-descriptions :column="1" border size="small"><el-descriptions-item label="店铺">{{ shopName }}</el-descriptions-item><el-descriptions-item label="商家编码">{{ binding.outer_id || '未填写' }}</el-descriptions-item><el-descriptions-item label="商品 ID">{{ binding.item_id }} <el-button v-clipboard:copy="binding.item_id" type="text" icon="el-icon-document-copy"/></el-descriptions-item><el-descriptions-item label="SKU ID">{{ binding.sku_id }} <el-button v-clipboard:copy="binding.sku_id" type="text" icon="el-icon-document-copy"/></el-descriptions-item><el-descriptions-item label="最近拉取">{{ binding.last_pull_at }}</el-descriptions-item></el-descriptions><el-button v-hasPermi="['channel:platform:log']" type="text" @click="showInteractions=!showInteractions">查看平台交互与报文</el-button><div class="current"><div class="label">当前绑定 · {{ source(binding.binding_source) }}</div><strong>{{ binding.oms_sku_sn || '尚未绑定' }}</strong><p>{{ binding.oms_goods_name }}</p><p class="muted">{{ binding.binding_reason || binding.match_issue }}</p></div></aside><main><template v-if="readOnly"><h3>当前绑定有效</h3><p>{{ binding.oms_goods_name }} · {{ binding.oms_sku_sn }}</p><p class="muted">没有变化时无需重复保存。更换 SKU 会影响后续新订单匹配及库存同步关系。</p><el-button type="primary" plain @click="readOnly=false;selectedSku='';selectedGoods=null">更换 OMS SKU</el-button></template><template v-else><h3>{{ binding.binding_state==='REVIEW'?'核对平台变化并确认目标 SKU':'选择 OMS 商品 / SKU' }}</h3><el-table v-if="changes.length" :data="changes" size="small" class="changes"><el-table-column prop="label" label="变化字段"/><el-table-column prop="before" label="上次值"/><el-table-column prop="after" label="当前值"/></el-table><el-alert v-if="suggestion" :title="suggestion.notice" type="info" :closable="false"/><div v-if="binding.binding_state==='REVIEW'&&binding.oms_sku_sn" class="keep"><el-button size="small" @click="keep">保留当前 OMS SKU {{ binding.oms_sku_sn }}</el-button></div><el-form inline size="small" class="search" @submit.native.prevent="search(true)"><el-select v-model="query.field" style="width:125px"><el-option label="SKU 编码" value="skuSn"/><el-option label="商品名称" value="goodsName"/><el-option label="条码" value="barcodeSn"/></el-select><el-input v-model.trim="query.keyword" placeholder="搜索 OMS 商品" style="width:260px" @keyup.enter.native="search(true)"/><el-button @click="search(true)">搜索</el-button></el-form><p class="muted">推荐候选依据商家编码精确匹配；名称与规格请人工核对。点击“选择”后才会作为提交目标。</p><el-table v-loading="searching" :data="candidates" size="small"><el-table-column prop="sku_sn" label="OMS SKU" min-width="165"/><el-table-column label="商品 / 规格" min-width="200"><template slot-scope="s">{{ s.row.goods_name }}<div class="muted">{{ s.row.color_name || '—' }} / {{ s.row.size_name || '—' }}</div></template></el-table-column><el-table-column prop="barcode_sn" label="条码" min-width="100"/><el-table-column width="80"><template slot-scope="s"><el-button type="text" @click="select(s.row)">{{ selectedSku===s.row.sku_sn?'已选择':'选择' }}</el-button></template></el-table-column></el-table><pagination v-if="total>20" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="search(false)"/><div v-if="selectedSku" class="selected"><div class="label">已选目标 · {{ selectedGoods ? goodsType(selectedGoods) : '' }}</div><strong>{{ selectedSku }}</strong><p>{{ selectedGoods&&selectedGoods.goods_name }}</p><p>平台规格：{{ binding.spec_name || '无规格' }}<br>OMS 规格：{{ selectedGoods&&selectedGoods.color_name || '—' }} / {{ selectedGoods&&selectedGoods.size_name || '—' }}</p><el-tag size="mini" :type="binding.outer_id.trim()===selectedSku?'success':'warning'">{{ binding.outer_id.trim()===selectedSku?'编码一致，仍需核对规格':'编码不同，请核对绑定依据' }}</el-tag></div></template><el-dropdown class="more" @command="actionChanged"><el-button type="text">更多操作 <i class="el-icon-arrow-down"/></el-button><el-dropdown-menu slot="dropdown"><el-dropdown-item command="UNBIND">解除绑定（停止自动重绑）</el-dropdown-item><el-dropdown-item command="IGNORE">忽略此规格</el-dropdown-item><el-dropdown-item command="BIND">恢复 / 选择绑定</el-dropdown-item></el-dropdown-menu></el-dropdown><el-alert v-if="action!=='BIND'" :title="action==='IGNORE'?'忽略后不参与自动绑定，后续可手工恢复。':'解绑后保留平台商品资料，停止自动重绑，后续可手工恢复。'" type="warning" :closable="false"/><el-alert v-if="blocked" title="该链接仍受库存同步管理。请先清零并退出原关系，再执行此操作。" type="warning" :closable="false"/><div v-if="(binding.sync_references||[]).length"><p v-for="r in binding.sync_references" :key="r.id"><el-button type="text" @click="sync(r)">前往同步组 {{ r.group_id }} · {{ r.sku_sn }}</el-button></p><p v-if="binding.binding_state==='REVIEW'&&!blocked" class="warn">确认核对将更新绑定版本，原库存同步配置需重新核对并选择有效绑定版本。</p></div><template v-if="!readOnly"><el-input v-model="reason" type="textarea" :rows="3" maxlength="255" show-word-limit placeholder="填写核对、换绑、解绑或忽略依据"/><p class="muted">确认后用于后续订单匹配；已登记订单需求保留原 SKU。库存同步按独立配置执行。</p></template></main></div><el-collapse v-model="expanded"><el-collapse-item title="绑定处理记录" name="events"><el-table :data="binding.events" size="small"><el-table-column prop="create_time" label="时间" width="165"/><el-table-column label="操作"><template slot-scope="s">{{ eventLabel(s.row.action) }}</template></el-table-column><el-table-column label="SKU 变化"><template slot-scope="s">{{ s.row.from_sku || '未绑定' }} → {{ s.row.to_sku || '未绑定' }}</template></el-table-column><el-table-column prop="reason" label="依据" min-width="240"/><el-table-column prop="actor" label="操作者"/></el-table></el-collapse-item></el-collapse><product-interactions v-if="showInteractions" :channel-id="binding.channel_id" :item-id="binding.item_id"/></template></div><div class="drawer-footer"><el-button @click="visible=false">关闭</el-button><el-button v-if="binding&&!readOnly" type="primary" :disabled="!canSave" :loading="busy" @click="submit(false)">{{ submitLabel }}</el-button><el-button v-if="binding&&!readOnly&&hasNext" :disabled="!canSave" :loading="busy" @click="submit(true)">保存并处理下一条</el-button></div></el-drawer></template>
<script>
import {productGet,productPost} from '@/api/channel/products'
import ProductInteractions from './ProductInteractions'
const normalize=g=>({...g,sku_sn:g.sku_sn||g.skuSn,goods_name:g.goods_name||g.goodsName,color_name:g.color_name||g.colorName,size_name:g.size_name||g.sizeName,barcode_sn:g.barcode_sn||g.barcodeSn,is_package:g.is_package==null?g.isPackage:g.is_package,is_fd:g.is_fd==null?g.isFd:g.is_fd})
export default {name:'ProductBindingDrawer',components:{ProductInteractions},props:{queue:{type:Array,default:()=>[]},shopName:String},data(){return{visible:false,loading:false,error:'',binding:null,readOnly:false,action:'BIND',selectedSku:'',selectedGoods:null,candidates:[],total:0,suggestion:null,reason:'',query:{field:'skuSn',keyword:'',pageNum:1,pageSize:20},searching:false,busy:false,seq:0,searchSeq:0,showInteractions:false,expanded:[]}},computed:{heading(){return this.binding?this.binding.binding_state==='REVIEW'?'核对平台商品绑定':this.readOnly?'查看商品绑定':'确认平台商品绑定':'商品绑定'},blocked(){return this.binding&&(this.binding.sync_references||[]).length>0&&(this.action!=='BIND'||!!this.selectedSku&&this.selectedSku!==this.binding.oms_sku_sn)},canSave(){return this.binding&&!this.blocked&&!!this.reason.trim()&&(this.action!=='BIND'||!!this.selectedSku)&&!(this.action==='BIND'&&this.binding.binding_state==='BOUND'&&this.selectedSku===this.binding.oms_sku_sn)},submitLabel(){return this.action==='IGNORE'?'确认忽略':this.action==='UNBIND'?'确认解绑':this.binding.binding_state==='REVIEW'?'确认核对':this.binding.oms_sku_sn?'确认换绑':'确认绑定'},changes(){if(!this.binding||this.binding.binding_state!=='REVIEW')return[];const e=(this.binding.events||[]).find(x=>x.action==='IDENTITY_CHANGED');if(!e)return[];try{const s=typeof e.snapshot_json==='string'?JSON.parse(e.snapshot_json):e.snapshot_json;return [['outer_id','商家编码'],['properties','规格属性'],['platform_shop_id','平台店铺身份']].filter(([k])=>s.before&&s.after&&s.before[k]!==s.after[k]).map(([k,label])=>({label,before:s.before[k]||'未填写',after:s.after[k]||'未填写'}))}catch(_){return[]}},next(){if(!this.binding)return null;const i=this.queue.findIndex(x=>x.id===this.binding.id);return this.queue.slice(i+1).find(x=>x.present&&['UNBOUND','REVIEW'].includes(x.binding_state))},hasNext(){return!!this.next}},beforeDestroy(){this.seq++;this.searchSeq++},methods:{source(s){return {AUTO:'自动绑定',MANUAL:'人工处理'}[s]||'待处理'},eventLabel(s){return {BIND:'人工绑定',UNBIND:'解除绑定',IGNORE:'忽略规格',AUTO_BIND:'自动绑定',IDENTITY_CHANGED:'平台身份变化',SPEC_REMOVED:'规格已移除'}[s]||s},goodsType(g){if(g.goods_type)return {NORMAL:'普通商品',STOCKED:'实物套装',VIRTUAL:'虚拟套装',LUCKY_BAG:'福袋',KIT_UNPUBLISHED:'套装未发布'}[g.goods_type]||g.goods_type;return Number(g.is_fd)?'福袋':Number(g.is_package)?'套装':'普通商品'},async open(row){const seq=++this.seq;this.searchSeq++;this.visible=true;this.loading=true;this.error='';this.binding=null;this.reason='';this.selectedSku='';this.selectedGoods=null;this.candidates=[];this.total=0;this.suggestion=null;this.action='BIND';this.showInteractions=false;try{const b=(await productGet('/'+row.id)).data;if(seq!==this.seq)return;this.binding=b;this.readOnly=b.binding_state==='BOUND';this.query={field:'skuSn',keyword:b.outer_id||'',pageNum:1,pageSize:20};const s=(await productGet('/'+row.id+'/suggestions')).data;if(seq===this.seq){this.suggestion=s;this.candidates=s.candidates.map(normalize);if(b.binding_state==='REVIEW')this.keep()}}catch(_){if(seq===this.seq)this.error='绑定资料读取失败，请关闭后重试'}finally{if(seq===this.seq)this.loading=false}},async search(reset){if(reset)this.query.pageNum=1;const seq=++this.searchSeq;this.searching=true;try{const r=(await productPost('/goods/search',this.query)).data;if(seq===this.searchSeq){this.candidates=r.rows.map(normalize);this.total=r.total}}finally{if(seq===this.searchSeq)this.searching=false}},select(g){this.selectedSku=g.sku_sn;this.selectedGoods=g;this.action='BIND'},keep(){this.selectedSku=this.binding.oms_sku_sn||'';this.selectedGoods=this.candidates.find(g=>g.sku_sn===this.selectedSku)||{goods_name:this.binding.oms_goods_name,sku_sn:this.selectedSku,goods_type:this.binding.goods_type}},actionChanged(s){this.action=s;this.readOnly=false;if(s==='BIND')this.selectedSku=''},sync(r){this.visible=false;this.$router.push({path:'/oms-inventory/platformStock',query:{id:r.group_id}})},async submit(next){if(!this.canSave||this.busy)return;this.busy=true;const target=this.next;try{await productPost('/'+this.binding.id+'/binding',{action:this.action,sku_sn:this.selectedSku,reason:this.reason,binding_revision:this.binding.binding_revision});this.$message.success('绑定处理已保存');this.$emit('saved');if(next&&target)await this.open(target);else this.visible=false}finally{this.busy=false}}}}
</script><style scoped>.binding-workspace{padding:0 24px 100px}.compare{display:grid;grid-template-columns:330px minmax(0,1fr);gap:28px}.compare aside{padding:20px;background:#f5f8fc;border-radius:8px;align-self:start;position:sticky;top:0}.label,.muted{color:#7d899b;font-size:13px;line-height:1.7}.spec{font-size:16px;margin:14px 0}.picture{width:100px;height:100px;margin-top:14px}.current,.selected{padding:16px;margin:16px 0;border:1px solid #dce6ef;border-radius:6px;overflow-wrap:anywhere}.selected{background:#f1f8ff}.current strong,.selected strong{display:block;margin-top:10px}.search,.keep{margin:18px 0}.more{margin:16px 0}.warn{color:#a76812;font-size:13px}.drawer-footer{position:absolute;bottom:0;left:0;right:0;display:flex;justify-content:flex-end;gap:10px;background:#fff;padding:16px 24px;border-top:1px solid #e5eaf1;z-index:2}.el-collapse{margin-top:24px}@media(max-width:900px){.compare{grid-template-columns:1fr}.compare aside{position:static}}</style>
